static void on_message(union sigval sv) {
    mqd_t q = *(mqd_t *)sv.sival_ptr;
    struct sigevent sev = { .sigev_notify = SIGEV_THREAD,
                            .sigev_notify_function = on_message,
                            .sigev_value = sv };
    mq_notify(q, &sev);              /* re-arm first: notification is one-shot */
    char buf[MSG_MAX];
    while (mq_receive(q, buf, sizeof buf, NULL) > 0)
        handle_message(buf);         /* the listener */
}
